-- =====================================================================
-- FUTAHUB Supabase setup (rebuild file)
-- Run this whole file in Supabase > SQL Editor on a NEW, empty project.
-- IMPORTANT: this file does not contain any rows of data (no users, posts or
-- listings). It only rebuilds the structure and the security rules.
--
-- What is NOT captured in the backup data (check these by hand):
--   * Foreign keys, CHECK constraints and indexes (only primary keys are
--     added below, and they are ASSUMED)
--   * Identity settings for the id columns (ASSUMED: generated by default)
--   * Bucket extras such as file size limits and allowed file types
--   * The event trigger that uses rls_auto_enable() (see the end of the file)
--   * Which user is your admin (see the end of the file)
-- =====================================================================


-- ---------------------------------------------------------------------
-- 1. TABLES
-- ---------------------------------------------------------------------

create table if not exists public.admins (
  user_id uuid primary key,                       -- primary key ASSUMED
  created_at timestamptz not null default now()
);

create table if not exists public.profiles (
  id uuid primary key,                            -- primary key ASSUMED
  display_name text,
  avatar_url text,
  created_at timestamptz not null default now(),
  is_suspended boolean not null default false
);

create table if not exists public.listings (
  id bigint generated by default as identity primary key,   -- ASSUMED
  created_at timestamptz not null default now(),
  user_id uuid not null,
  section text not null,
  lost_found_type text,
  title text,
  description text,
  price numeric,
  contact_whatsapp text,
  location text,
  image_urls text[] not null default '{}'::text[],
  video_url text,
  file_url text,
  file_name text,
  details jsonb not null default '{}'::jsonb,
  updated_at timestamptz not null default now(),
  status text not null default 'active'::text,
  item_condition text,
  fulfilment text,
  level text,
  tutor_name text,
  organiser_name text,
  event_date date,
  start_time time without time zone,
  end_time time without time zone,
  is_pinned boolean not null default false
);

create table if not exists public.post_reports (
  id bigint generated by default as identity primary key,   -- ASSUMED
  created_at timestamptz not null default now(),
  listing_id bigint not null,
  reporter_id uuid,
  reason text not null,
  status text not null default 'open'::text
);

-- Older posts table (kept because the app may still use it)
create table if not exists public.posts (
  id bigint generated by default as identity primary key,   -- ASSUMED
  created_at timestamptz not null default now(),
  "Name" text default 'NULL'::text,
  category text default 'Campus gist'::text,
  content text default ''::text,
  user_id uuid default auth.uid(),
  image_url text,
  name text default 'FUTA Student'::text,
  file_url text,
  file_name text,
  price numeric,
  item_condition text,
  whatsapp text,
  location text,
  title text,
  attachments jsonb not null default '[]'::jsonb,
  "text" text,
  image text,
  "time" text,
  details jsonb
);

create table if not exists public.reports (
  id bigint generated by default as identity primary key,   -- ASSUMED
  post_id bigint,
  reporter_id uuid default auth.uid(),
  reason text default 'Reported'::text,
  created_at timestamptz default now()
);

create table if not exists public.saved_posts (
  user_id uuid not null,
  listing_id bigint not null,
  created_at timestamptz not null default now(),
  primary key (user_id, listing_id)                         -- ASSUMED
);


-- ---------------------------------------------------------------------
-- 2. TURN ON ROW LEVEL SECURITY (it was ON for all 7 tables)
-- ---------------------------------------------------------------------

alter table public.admins       enable row level security;
alter table public.profiles     enable row level security;
alter table public.listings     enable row level security;
alter table public.post_reports enable row level security;
alter table public.posts        enable row level security;
alter table public.reports      enable row level security;
alter table public.saved_posts  enable row level security;


-- ---------------------------------------------------------------------
-- 3. FUNCTIONS (copied exactly from the backup)
-- ---------------------------------------------------------------------

CREATE OR REPLACE FUNCTION public.is_admin()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select exists (select 1 from public.admins where user_id = (select auth.uid()))
$function$;

CREATE OR REPLACE FUNCTION public.is_active_user()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select not exists (
    select 1 from public.profiles
    where id = (select auth.uid()) and is_suspended
  )
$function$;

CREATE OR REPLACE FUNCTION public.set_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin new.updated_at = now(); return new; end $function$;

CREATE OR REPLACE FUNCTION public.handle_new_user()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  insert into public.profiles (id, display_name)
  values (new.id, coalesce(nullif(trim(new.raw_user_meta_data->>'full_name'), ''), split_part(new.email, '@', 1)))
  on conflict (id) do nothing;
  return new;
end $function$;

CREATE OR REPLACE FUNCTION public.rls_auto_enable()
 RETURNS event_trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  cmd record;
  tbl name;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        SELECT c.relname INTO tbl FROM pg_catalog.pg_class c WHERE c.oid = cmd.objid;
        EXECUTE format('alter table if exists %I.%I enable row level security', cmd.schema_name, tbl);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$function$;


-- ---------------------------------------------------------------------
-- 4. TRIGGERS (only your own ones; Supabase manages the storage/realtime ones)
-- ---------------------------------------------------------------------

CREATE TRIGGER listings_set_updated_at
  BEFORE UPDATE ON public.listings
  FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();

-- Creates a profile row automatically when someone signs up
CREATE TRIGGER on_auth_user_created
  AFTER INSERT ON auth.users
  FOR EACH ROW EXECUTE FUNCTION public.handle_new_user();


-- ---------------------------------------------------------------------
-- 5. STORAGE BUCKETS (all three were public)
-- ---------------------------------------------------------------------

insert into storage.buckets (id, name, public) values
  ('post-images', 'post-images', true),
  ('post-videos', 'post-videos', true),
  ('post-files',  'post-files',  true)
on conflict (id) do nothing;


-- ---------------------------------------------------------------------
-- 6. SECURITY RULES (POLICIES) - copied from the backup
-- ---------------------------------------------------------------------

-- admins
create policy "Users can check their own admin row" on public.admins as PERMISSIVE for SELECT to authenticated using ((user_id = ( SELECT auth.uid() AS uid)));

-- listings
create policy "Admins can edit any listing" on public.listings as PERMISSIVE for UPDATE to authenticated using (is_admin()) with check (is_admin());
create policy "Signed-in users can read listings" on public.listings as PERMISSIVE for SELECT to authenticated using (true);
create policy "Users can edit their own listings" on public.listings as PERMISSIVE for UPDATE to authenticated using (((user_id = ( SELECT auth.uid() AS uid)) AND is_active_user())) with check (((user_id = ( SELECT auth.uid() AS uid)) AND is_active_user() AND ((section <> 'announcements'::text) OR is_admin())));
create policy "Users can post their own listings" on public.listings as PERMISSIVE for INSERT to authenticated with check (((user_id = ( SELECT auth.uid() AS uid)) AND is_active_user() AND ((section <> 'announcements'::text) OR is_admin())));
create policy "Users delete own listings, admins delete any" on public.listings as PERMISSIVE for DELETE to authenticated using (((user_id = ( SELECT auth.uid() AS uid)) OR is_admin()));

-- post_reports
create policy "Admins delete reports" on public.post_reports as PERMISSIVE for DELETE to authenticated using (is_admin());
create policy "Admins read reports" on public.post_reports as PERMISSIVE for SELECT to authenticated using (is_admin());
create policy "Admins update reports" on public.post_reports as PERMISSIVE for UPDATE to authenticated using (is_admin()) with check (is_admin());
create policy "Users can report posts" on public.post_reports as PERMISSIVE for INSERT to authenticated with check ((reporter_id = ( SELECT auth.uid() AS uid)));

-- posts (several of these do the same thing; harmless duplicates)
create policy "Anyone can read posts" on public.posts as PERMISSIVE for SELECT to anon, authenticated using (true);
create policy "Anyone can view posts" on public.posts as PERMISSIVE for SELECT to anon, authenticated using (true);
create policy "Authenticated users can create posts" on public.posts as PERMISSIVE for INSERT to authenticated with check ((auth.uid() = user_id));
create policy "Posts are publicly readable" on public.posts as PERMISSIVE for SELECT to anon, authenticated using (true);
create policy "Posts are readable by everyone" on public.posts as PERMISSIVE for SELECT to anon, authenticated using (true);
create policy "Users can create their own posts" on public.posts as PERMISSIVE for INSERT to authenticated with check ((auth.uid() = user_id));
create policy "Users can delete their own posts" on public.posts as PERMISSIVE for DELETE to authenticated using ((auth.uid() = user_id));
create policy "Users can edit their own posts" on public.posts as PERMISSIVE for UPDATE to authenticated using ((auth.uid() = user_id)) with check ((auth.uid() = user_id));
create policy "Users can update their own posts" on public.posts as PERMISSIVE for UPDATE to authenticated using ((auth.uid() = user_id)) with check ((auth.uid() = user_id));
create policy "admin can delete any post" on public.posts as PERMISSIVE for DELETE to authenticated using (((auth.jwt() ->> 'email'::text) = 'ayatullahadegoke@gmail.com'::text));
create policy futa_live_delete_own_posts on public.posts as PERMISSIVE for DELETE to authenticated using ((auth.uid() = user_id));
create policy futa_live_insert_posts on public.posts as PERMISSIVE for INSERT to authenticated with check ((auth.uid() = user_id));
create policy futa_live_read_posts on public.posts as PERMISSIVE for SELECT to anon, authenticated using (true);
create policy futa_live_update_own_posts on public.posts as PERMISSIVE for UPDATE to authenticated using ((auth.uid() = user_id)) with check ((auth.uid() = user_id));

-- profiles
create policy "Signed-in users can see profiles" on public.profiles as PERMISSIVE for SELECT to authenticated using (true);
create policy "Users create their own profile" on public.profiles as PERMISSIVE for INSERT to authenticated with check ((id = ( SELECT auth.uid() AS uid)));
create policy "Users edit their own profile" on public.profiles as PERMISSIVE for UPDATE to authenticated using ((id = ( SELECT auth.uid() AS uid))) with check ((id = ( SELECT auth.uid() AS uid)));

-- reports
create policy "users can report posts" on public.reports as PERMISSIVE for INSERT to authenticated with check ((reporter_id = auth.uid()));

-- saved_posts
create policy "Users read their own saved posts" on public.saved_posts as PERMISSIVE for SELECT to authenticated using ((user_id = ( SELECT auth.uid() AS uid)));
create policy "Users remove their own saved posts" on public.saved_posts as PERMISSIVE for DELETE to authenticated using ((user_id = ( SELECT auth.uid() AS uid)));
create policy "Users save posts for themselves" on public.saved_posts as PERMISSIVE for INSERT to authenticated with check ((user_id = ( SELECT auth.uid() AS uid)));

-- storage.objects (uploads)
create policy "Signed-in users can read uploads" on storage.objects as PERMISSIVE for SELECT to authenticated using ((bucket_id = ANY (ARRAY['post-images'::text, 'post-videos'::text, 'post-files'::text])));
create policy "Users delete their own uploads, admins delete any" on storage.objects as PERMISSIVE for DELETE to authenticated using (((bucket_id = ANY (ARRAY['post-images'::text, 'post-videos'::text, 'post-files'::text])) AND (((storage.foldername(name))[1] = (( SELECT auth.uid() AS uid))::text) OR is_admin())));
create policy "Users upload documents to their own folder" on storage.objects as PERMISSIVE for INSERT to authenticated with check (((bucket_id = 'post-files'::text) AND ((storage.foldername(name))[1] = (( SELECT auth.uid() AS uid))::text)));
create policy "Users upload photos and videos to their own folder" on storage.objects as PERMISSIVE for INSERT to authenticated with check (((bucket_id = ANY (ARRAY['post-images'::text, 'post-videos'::text])) AND ((storage.foldername(name))[1] = (( SELECT auth.uid() AS uid))::text)));


